function validate([rooms, queries]) {
  if (rooms.length < 1 || rooms.length > 100000) return 'rooms needs 1 to 10^5 entries.';
  if (queries.length < 1 || queries.length > 10000) return 'queries needs 1 to 10^4 entries.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 10000000;
  const seen = new Set();
  for (const room of rooms) {
    if (!Array.isArray(room) || room.length !== 2) return 'Each room is [roomId, size].';
    if (!ok(room[0]) || !ok(room[1])) return 'Room numbers and sizes are integers from 1 to 10^7.';
    if (seen.has(room[0])) return 'Room numbers must be distinct.';
    seen.add(room[0]);
  }
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is [preferred, minSize].';
    if (!ok(query[0]) || !ok(query[1])) return 'preferred and minSize are integers from 1 to 10^7.';
  }
  return null;
}

