function closestRoom(rooms, queries) {
  const lowerBound = (list, target) => {
    let low = 0;
    let high = list.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (list[mid] < target) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low;
  };
  const roomsBySize = [...rooms].sort((a, b) => b[1] - a[1]);
  const order = queries.map((_, index) => index);
  order.sort((a, b) => queries[b][1] - queries[a][1]);
  const ids = [];
  const answer = new Array(queries.length).fill(-1);
  let next = 0;
  for (const index of order) {
    const [preferred, minSize] = queries[index];
    while (next < roomsBySize.length && roomsBySize[next][1] >= minSize) {
      const id = roomsBySize[next][0];
      ids.splice(lowerBound(ids, id), 0, id);
      next++;
    }
    const pos = lowerBound(ids, preferred);
    let best = -1;
    if (pos > 0) {
      best = ids[pos - 1];
    }
    if (pos < ids.length && (best === -1 || ids[pos] - preferred < preferred - best)) {
      best = ids[pos];
    }
    answer[index] = best;
  }
  return answer;
}

