function closestRoom(rooms, queries) {
  return queries.map(([preferred, minSize]) => {
    let chosen = -1;
    for (const [id, size] of rooms) {
      if (size < minSize) continue;
      if (chosen === -1) { chosen = id; continue; }
      const d1 = Math.abs(id - preferred);
      const d2 = Math.abs(chosen - preferred);
      if (d1 < d2 || (d1 === d2 && id < chosen)) chosen = id;
    }
    return chosen;
  });
}

