function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 6);
  const k = large ? 2000 : 1 + Math.floor(rand() * 6);
  const idLimit = large ? 10000000 : 15;
  const sizeLimit = large ? 10000000 : 6;
  const used = new Set();
  const rooms = [];
  while (rooms.length < n) {
    const id = 1 + Math.floor(rand() * idLimit);
    if (used.has(id)) continue;
    used.add(id);
    rooms.push([id, 1 + Math.floor(rand() * sizeLimit)]);
  }
  const queries = Array.from({ length: k }, () => [
    1 + Math.floor(rand() * (large ? idLimit : idLimit + 3)),
    1 + Math.floor(rand() * (large ? sizeLimit : sizeLimit + 1)),
  ]);
  return [rooms, queries];
}
